fn lanes(v:&[f64]) -> f64 { let mut m=[0.0f64;8]; let mut b=[0.0f64;8]; let (ch,tail)=v.as_chunks::<8>(); for c in ch { for ((m,b),&x) in m.iter_mut().zip(&mut b).zip(c) { let a=x.abs(); *m = if a>*m {a} else {*m}; *b += x*0.0; } } for ((m,b),&x) in m.iter_mut().zip(&mut b).zip(tail) { let a=x.abs(); *m = if a>*m {a} else {*m}; *b+=x*0.0;} assert!(!b.iter().any(|x| x.is_nan())); m.into_iter().fold(0.0,f64::max) }
fn serial(v:&[f64]) -> f64 { let mut m=0.0f64; for &x in v { if !x.is_finite() {panic!()} m=m.max(x.abs()); } m }
fn scaled_rows(d:&DMatrix<f64>, f:f64) -> Vec<Vec<f64>> { let mut rows = vec![Vec::with_capacity(d.ncols()); d.nrows()]; for c in d.as_slice().chunks_exact(d.nrows()) { for (r,&x) in rows.iter_mut().zip(c) { r.push(x*f); } } rows }
