  let all: Vec<usize> = (1..=80).collect();
  t("ifb 80 bins", 300, || est.ifb_music_spectrum(&data,160,1,Some(&all)).unwrap());
  let active: Vec<usize> = (2..=78).step_by(4).collect();
  t("ifb 20 active bins only", 500, || est.ifb_music_spectrum(&data,160,1,Some(&active)).unwrap());
  t("ifb bins 1..=80 (60 silent, skipped)", 500, || est.ifb_music_spectrum(&data,160,1,Some(&all)).unwrap());
  t("ifb bin 14 only", 1000, || est.ifb_music_spectrum(&data,160,1,Some(&[14])).unwrap());
  println!("== shared preprocessing");
  t("max-abs + finite: serial f64::max fold", 1000, || serial(data.as_slice()));
  t("max-abs + finite: 8 lanes", 1000, || lanes(data.as_slice()));
  t("old: nalgebra data / scale (copy)", 1000, || &data / 2.0);
  t("old: data.row(m) copies x4", 1000, || (0..4).map(|m| data.row(m).iter().copied().collect::<Vec<f64>>()).collect::<Vec<_>>());
  t("scaled_rows (one pass)", 1000, || scaled_rows(&data, 0.5));
  t("alt: zeroed rows + strided writes", 1000, || { let s = data.as_slice(); let nr = data.nrows(); (0..nr).map(|i| { let mut r = vec![0.0; data.ncols()]; for (o,x) in r.iter_mut().zip(s[i..].iter().step_by(nr)) { *o = x*0.5; } r }).collect::<Vec<_>>() });
  let rows = scaled_rows(&data, 1.0);
  println!("== narrowband");
  let n = rows[0].len();
  let mut cplan = rustfft::FftPlanner::<f64>::new();
  let (ff, fi) = (cplan.plan_fft_forward(n), cplan.plan_fft_inverse(n));
  t("analytic signal x4 (complex FFT + IFFT)", 300, || { rows.iter().map(|r| { let mut b: Vec<C> = r.iter().map(|&x| C::new(x,0.0)).collect(); ff.process(&mut b); for x in &mut b[1..n/2] { *x *= 2.0; } for x in &mut b[n/2+1..] { *x = C::new(0.0,0.0);} fi.process(&mut b); b }).collect::<Vec<_>>() });
  let z: Vec<Vec<C>> = rows.iter().map(|r| musicrs::analytic_signal(r)).collect();
  t("covariance Z Z^H over 16000 samples", 300, || { let mut c = DMatrix::<C>::zeros(4,4); for i in 0..4 { for j in 0..=i { let s: C = z[i].iter().zip(&z[j]).map(|(a,b)| a*b.conj()).sum(); c[(i,j)]=s; c[(j,i)]=s.conj(); } } c });
  let rp = realfft::RealFftPlanner::<f64>::new().plan_fft_forward(n);
  let mut rows2 = rows.clone();
  t("real FFT x4 (in place of FFT+IFFT)", 300, || { let mut s = rp.make_scratch_vec(); rows2.iter_mut().map(|r| { let mut o = rp.make_output_vec(); rp.process_with_scratch(r,&mut o,&mut s).unwrap(); o }).collect::<Vec<_>>() });
  let sp: Vec<Vec<C>> = rows.iter().map(|r| { let mut r = r.clone(); let mut o = rp.make_output_vec(); rp.process(&mut r,&mut o).unwrap(); o }).collect();
