  let cov = { let mut c = DMatrix::<C>::zeros(4,4); for i in 0..4 { for j in 0..4 { c[(i,j)] = z[i].iter().zip(&z[j]).map(|(a,b)| a*b.conj()).sum::<C>() / n as f64; } } c };
  t("noise_subspace (faer Hermitian eig, 4x4)", 3000, || est.noise_subspace(&cov,1).unwrap());
  let nm = est.noise_subspace(&cov,1).unwrap();
  t("spectrum, 720 angles", 2000, || est.spectrum(&nm,1400.0).unwrap());
  for f in [100.0, 1400.0, 4000.0, 7900.0] { t(&format!("spectrum at {f} Hz"), 2000, || est.spectrum(&nm,f).unwrap()); }
  t("720 x 4 from_polar only", 2000, || { let mut s = C::new(0.0,0.0); for k in 0..720 { let th = k as f64 * 0.0087266; for p in &est.antenna_positions { s += C::from_polar(1.0, 2.0*std::f64::consts::PI*1400.0*(p[0]*th.cos()+p[1]*th.sin())/343.2); } } s });
  println!("== ifb");
  t("stft x4, real FFT, nfft 160", 1000, || rows.iter().map(|r| musicrs::stft(r,160,0).unwrap()).collect::<Vec<_>>());
  let st: Vec<Vec<Vec<C>>> = rows.iter().map(|r| musicrs::stft(r,160,0).unwrap()).collect();
  t("old: complex FFT, new Vec per window x4", 1000, || { let f = cplan.plan_fft_forward(160); let mut res = vec![vec![C::new(0.0,0.0);100];81]; for r in &rows { for (w,c) in r.chunks_exact(160).enumerate() { let mut b: Vec<C> = c.iter().map(|&x| C::new(x,0.0)).collect(); f.process(&mut b); for k in 0..81 { res[k][w]=b[k]; } } } res });
  t("power of every bin (silence reference)", 1000, || { let mut p = vec![0.0;81]; for m in &st { for (pp,b) in p.iter_mut().zip(m) { *pp += b.iter().map(|c| c.norm_sqr()).sum::<f64>()/100.0; } } p });
  t("old: cov 1 bin via nalgebra outer products", 3000, || { let mut c = DMatrix::<C>::zeros(4,4); for w in 0..100 { let col = nalgebra::DVector::from_iterator(4, st.iter().map(|s| s[14][w])); c += &col * col.adjoint(); } c });
  t("cov 1 bin, direct sums", 3000, || { let mut c = DMatrix::<C>::zeros(4,4); for i in 0..4 { for j in 0..=i { let s: C = st[i][14].iter().zip(&st[j][14]).map(|(a,b)| a*b.conj()).sum(); c[(i,j)]=s; c[(j,i)]=s.conj(); } } c });
